func writeSnapshotDir(root string, snap worktreeSnapshot, files []string) error {
	for _, file := range files {
		entry := snap[file]
		if !entry.exists {
			continue
		}
		target := filepath.Join(root, filepath.FromSlash(file))
		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(target, entry.data, 0o644); err != nil {
			return err
		}
	}
	return nil
}

func normalizeSnapshotDiff(out string) string {
	lines := strings.Split(out, "\n")
	for i, line := range lines {
		switch {
		case strings.HasPrefix(line, "diff --git "):
			lines[i] = normalizeDiffGitLine(line)
		case strings.HasPrefix(line, "--- before/"):
			lines[i] = "--- a/" + strings.TrimPrefix(line, "--- before/")
		case strings.HasPrefix(line, "--- after/"):
			lines[i] = "--- a/" + strings.TrimPrefix(line, "--- after/")
		case strings.HasPrefix(line, "+++ before/"):
			lines[i] = "+++ b/" + strings.TrimPrefix(line, "+++ before/")
		case strings.HasPrefix(line, "+++ after/"):
			lines[i] = "+++ b/" + strings.TrimPrefix(line, "+++ after/")
		}
	}
	return strings.Join(lines, "\n")
}

func normalizeDiffGitLine(line string) string {
	parts := strings.Fields(strings.TrimPrefix(line, "diff --git "))
	if len(parts) != 2 {
		return line
	}
	left := strings.TrimPrefix(strings.TrimPrefix(parts[0], "before/"), "after/")
	right := strings.TrimPrefix(strings.TrimPrefix(parts[1], "before/"), "after/")
	if right == "" {
		right = left
	}
	if left == "" {
		left = right
	}
	return "diff --git a/" + left + " b/" + right
}

